async function retry(fn, { retries = 3, base = 200 } = {}) {
  let attempt = 0;
  while (true) {
    try {
      return await fn();
    } catch (err) {
      if (attempt >= retries) throw err;
      await delay(base * 2 ** attempt);
      attempt++;
    }
  }
}

