function createApp() {
  const stack = [];
  return {
    use(fn) { stack.push(fn); },
    handle(req, res) {
      let i = 0;
      const next = (err) => {
        if (err) return res.end('error: ' + err.message);
        const fn = stack[i++];
        if (!fn) return res.end();
        fn(req, res, next);
      };
      next();
    },
  };
}

