function memoizeAsync(fn, ttl = 5000) {
  const cache = new Map();
  return async function (key) {
    const hit = cache.get(key);
    if (hit && Date.now() - hit.t < ttl) return hit.p;
    const p = fn(key);
    cache.set(key, { p, t: Date.now() });
    try {
      return await p;
    } catch (err) {
      cache.delete(key); // don't cache failures
      throw err;
    }
  };
}

