function runHeavy(n) {
  return new Promise((resolve, reject) => {
    const worker = new Worker('./heavy.js', { workerData: n });
    worker.on('message', resolve);
    worker.on('error', reject);
    worker.on('exit', (code) => {
      if (code !== 0) reject(new Error('worker exited ' + code));
    });
  });
}

