// Sequential (slow): each await blocks the next iteration
async function slow(urls) {
  const out = [];
  for (const u of urls) out.push(await fetch(u));
  return out;
}

// Parallel (fast): start all, then await together
async function fast(urls) {
  return Promise.all(urls.map((u) => fetch(u)));
}
